 L(a,h,GenSamplers);L(a,h,BindSampler);L(a,h,SamplerParameterf);L(a,h,DeleteSamplers);L(a,h,IsSampler);L(a,h,ActiveTexture);
 L(a,h,GenFramebuffers);L(a,h,BindFramebuffer);L(a,h,FramebufferTexture2D);L(a,h,CheckFramebufferStatus);L(a,h,DrawBuffer);L(a,h,ReadBuffer);L(a,h,BlitFramebuffer);L(a,h,DeleteFramebuffers);L(a,h,IsFramebuffer);
